// Stamps the crew's live facts into the pages that state them. The facts are
// data/crew-facts.json, GENERATED by OpenClaw's scripts/bridges/crew-facts.py
// from the live gateways and cron stores (never edit it by hand; its checkup
// row `crewfacts` turns red when it drifts from live). Each block sits between
// `<!-- crew:<kind>[:<arg>]:start -->` and its `:end`; everything outside the
// markers (each agent's personality copy) is hand-written and left alone.
const fs = require('fs');
const path = require('path');
const writeIfChanged = require('./lib/write-if-changed');

const ROOT = path.join(__dirname, '..');
const FACTS = JSON.parse(fs.readFileSync(path.join(ROOT, 'data', 'crew-facts.json'), 'utf8'));
const CREW_PAGE = 'public/zephyy/crew/index.html';
const PAGES = [CREW_PAGE, 'public/bot.html'];
const BLOCK = /^([ \t]*)<!-- crew:([a-z]+(?::[a-z0-9-]+)?):start -->\n[\s\S]*?^[ \t]*<!-- crew:\2:end -->/gm;

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const RENDER = {
    // One agent's model chain and schedule (cadence only, never a clock time).
    facts(id) {
        const agent = FACTS.agents.find((a) => a.id === id);
        if (!agent) throw new Error(`data/crew-facts.json has no agent "${id}"`);
        return ['<dl class="crew-facts">', '    <dt>Models</dt>', `    <dd>${agent.models.map(esc).join(' → ')}</dd>`]
            .concat(agent.schedule.length ? ['    <dt>Schedule</dt>'] : [])
            .concat(agent.schedule.map((s) => `    <dd>${esc(s.job)} · ${esc(s.cadence)}</dd>`))
            .concat('</dl>');
    },
    // The coding agents that build and review the system.
    operators() {
        return ['<dl class="crew-ops">']
            .concat(FACTS.operators.flatMap((op) => [`    <dt>${esc(op.name)}</dt>`, `    <dd>${esc(op.role || '')}</dd>`]))
            .concat('</dl>');
    },
    // The house User-Agent forms, from OpenClaw's scripts/lib/useragent.json.
    ua() {
        const ua = FACTS.userAgent;
        return ['<dl class="bot-ua">', '    <dt>Most requests</dt>', `    <dd><code>${esc(ua.default)}</code></dd>`]
            .concat(ua.forms.flatMap((f) => [
                `    <dt>Requests to ${f.hosts.map(esc).join(' and ')}</dt>`,
                `    <dd><code>${esc(f.form)}</code></dd>`
            ]))
            .concat('    <dt>Token to match</dt>', `    <dd><code>${esc(ua.token)}</code></dd>`, '</dl>');
    }
};

for (const page of PAGES) {
    const filePath = path.join(ROOT, page);
    const source = fs.readFileSync(filePath, 'utf8');
    const stamped = new Set();
    const updated = source.replace(BLOCK, (_, indent, key) => {
        const [kind, arg] = key.split(':');
        if (!RENDER[kind]) throw new Error(`${page}: unknown crew block "${kind}"`);
        stamped.add(key);
        const body = RENDER[kind](arg).map((line) => indent + line).join('\n');
        return `${indent}<!-- crew:${key}:start -->\n${body}\n${indent}<!-- crew:${key}:end -->`;
    });
    if (!stamped.size) throw new Error(`${page}: no crew markers found`);
    // An agent the gateways know but the crew page has no card for is drift too.
    if (page === CREW_PAGE) {
        for (const agent of FACTS.agents.filter((a) => !stamped.has(`facts:${a.id}`))) {
            process.exitCode = 1;
            console.log(`Drift: ${page} has no crew card for live agent "${agent.id}"`);
        }
    }
    writeIfChanged(filePath, source, updated);
}
